import {getProblem,colors,crimpOptions} from './problem.mjs';
import {Attempt,formatTime} from './engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=await fetch('./catalog.json').then(r=>{if(!r.ok)throw Error('문제 목록을 불러오지 못했습니다.');return r.json();});
catalog.sort((a,b)=>{const da=a.date.match(/\d+/g).slice(0,3).map(Number),db=b.date.match(/\d+/g).slice(0,3).map(Number);return da[0]-db[0]||da[1]-db[1]||da[2]-db[2];});
let p=getProblem(),attempt=new Attempt(),selectedDevice=null,selectedTerminal=null,highlight=null,zoom=100,boardZoom=100,docPage=5,currentView='home',editing=null,readerId='p01';
const top=()=>`<header class="top"><div class="brand"><span class="logo">PCQ</span><div><strong>배선 실습실</strong><small>PLC 제어기술자 3급</small></div></div><button id="home">문제 목록</button></header>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function home(){currentView='home';$('#app').innerHTML=top()+`<main class="wrap"><div class="eyebrow">WIRING PRACTICE</div><h1>도면을 읽고, 직접 배선해 보세요.</h1><p class="muted">26개 공개 기출문제에서 회로도와 배치도를 확인하고 3D 배선과 NET/JUMP 채점을 반복 연습할 수 있습니다.</p><section class="feature"><div><span class="chip">전체 기출문제 3D 실습</span><h1>PCQ 배선 실습실</h1><p>문제별 기구배치·제어회로·PLC 결선과 배선 규칙을 적용합니다.</p><div class="chips"><span class="chip">원본 1~6페이지</span><span class="chip">NET / JUMP 채점</span><span class="chip">문제별 정답 회로</span></div><a class="primary" href="3d.html?problem=p01" style="display:inline-block;padding:12px;border-radius:6px;margin-right:12px">3D 실습 시작</a><button id="enter">기존 2D 실습</button></div><img src="assets/board.webp" alt="PCQ 기구배치도"></section><h2>기출문제 선택 <span class="muted">26개 · 모두 3D 배선 실습 가능</span></h2><div class="catalog">${catalog.map(x=>`<article class="card"><div><strong>${esc(x.date)}</strong><div class="muted">3D 배선·채점 가능 · 절연튜브 ${x.tubeScope==='all'?'전체 단자':'입출력 단자'}</div></div><div class="card-actions"><a class="primary" href="3d.html?problem=${encodeURIComponent(x.id)}">3D 실습</a><button data-read="${x.id}">자료 보기</button></div></article>`).join('')}</div></main>`;$('#enter').onclick=()=>{resetAttempt();p=getProblem();session();};bindHome();document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>reader(b.dataset.read));}
function bindHome(){$('#home').onclick=()=>{if(attempt.state==='running'&&currentView==='session')confirmAction('문제 목록으로 이동','진행 중인 작업과 경과시간을 초기화하고 목록으로 이동하시겠습니까?',()=>{resetAttempt();home();});else home();};}
function docPanel(){return `<section class="panel"><div class="panelhead"><h2>문제 자료</h2><small>PDF 원본 · 1~6페이지</small></div><div class="tabs">${[[5,'제어회로도'],[6,'PLC · 인버터 · 내부결선'],[4,'기구배치'],[1,'배선 규칙 1'],[2,'배선 규칙 2'],[3,'요구사항']].map(([n,s])=>`<button data-page="${n}" class="${n===docPage?'active':''}">${s}</button>`).join('')}</div><div class="doccontrols"><button id="docminus" aria-label="도면 축소">−</button><span id="doczoom">${zoom}%</span><button id="docplus" aria-label="도면 확대">＋</button><button id="docfit">맞춤</button><button id="docopen">크게 보기</button></div><div class="docviewport"><img id="docimage" class="docimage" src="assets/${readerId}/${docPage}.webp" alt="${esc(catalog.find(x=>x.id===readerId).name)} ${docPage}페이지 원본" style="width:${zoom}%"></div></section>`;}
function bindDocs(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{docPage=Number(b.dataset.page);$('#docimage').src=`assets/${readerId}/${docPage}.webp`;$('#docimage').alt=`${catalog.find(x=>x.id===readerId).name} ${docPage}페이지 원본`;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));});const change=n=>{zoom=Math.max(50,Math.min(400,n));$('#docimage').style.width=zoom+'%';$('#doczoom').textContent=zoom+'%';};$('#docminus').onclick=()=>change(zoom-25);$('#docplus').onclick=()=>change(zoom+25);$('#docfit').onclick=()=>change(100);$('#docopen').onclick=()=>{const d=document.createElement('dialog');d.style.maxWidth='95vw';d.innerHTML=`<div class="panelhead"><h2>원본 ${docPage}페이지</h2><button>닫기</button></div><div style="max-height:80vh;overflow:auto"><img src="assets/${readerId}/${docPage}.webp" style="width:1100px;max-width:none" alt="원본 문제 자료"></div>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();};}
function reader(id){readerId=id;currentView='reader';docPage=5;zoom=100;const item=catalog.find(x=>x.id===id);$('#app').innerHTML=top()+`<main class="reader"><h1>${esc(item.name)}</h1><p class="muted">${esc(item.file)} · 원본 1~6페이지</p><p><a class="primary" href="3d.html?problem=${encodeURIComponent(id)}" style="display:inline-block;padding:11px 14px;border-radius:7px">이 문제 3D 실습</a></p>${docPanel()}</main>`;bindHome();bindDocs();}
function session(){currentView='session';readerId='p01';docPage=5;zoom=100;selectedDevice=null;selectedTerminal=null;highlight=null;editing=null;$('#app').innerHTML=top()+`<div class="sessionbar"><div class="sessiontitle"><strong>${p.name}</strong><div class="referencebar" id="stateLabel">문제 확인 · 시작 전</div></div><div><div class="clocklabel" id="clocklabel">경과시간</div><div class="timebox" id="clock">00:00:00</div></div><div class="actions"><button id="start" class="primary">시작</button><button id="finish" disabled>완료</button><button id="score" class="dark" disabled>채점하기</button></div></div><div class="notice"><span>확정된 연결·자재 규칙으로 부분 채점합니다. 제품별 실제 단자 위치와 Y형 체결 방향 등은 확인이 필요합니다.</span><button id="pending">확인 필요 보기</button></div><main class="workspace"><div><section class="panel"><div class="panelhead"><h2>배선 작업판 <small>700 × 600 mm</small></h2><div class="actions"><button id="boardminus" aria-label="작업판 축소">−</button><button id="boardplus" aria-label="작업판 확대">＋</button></div></div><div class="boardviewport"><div class="board" id="board"><img src="assets/board.webp" alt="PDF 4페이지 원본 기구배치도"><svg viewBox="0 0 698 599" id="wires"></svg>${p.devices.map(d=>`<button class="device" data-device="${d.id}" title="${d.id} 단자 선택" aria-label="${d.id} 단자 선택" style="left:${d.box[0]/698*100}%;top:${d.box[1]/599*100}%;width:${d.box[2]/698*100}%;height:${d.box[3]/599*100}%"></button>`).join('')}</div></div><div class="legend">기구 위치: 원본 그대로 · TB 단자: 원본 위치 · 그 외: 기구 선택 후 단자 목록에서 접속</div><div id="terminaldock" class="terminaldock"><div class="empty">기구를 클릭하면 연결 가능한 단자를 확인할 수 있습니다.</div></div></section><section class="panel materials" id="materials"><div class="panelhead"><h2>배선 도구</h2><label class="power">PLC 전원<select id="power"><option value="AC">AC 220V</option><option value="DC">DC 24V</option></select></label></div><div id="wireform"></div><div id="wirelist" class="wirelist"></div></section><section id="results" class="panel results" hidden></section></div><div>${docPanel()}<section class="panel" style="margin-top:14px"><div class="panelhead"><h2>이번 문제의 작업 기준</h2></div><div class="rulesdetails"><ul><li>주회로: 2.5㎟ 단선 · L1 갈색 / L2 검은색 / L3 회색 / N 도면 지정</li><li>보조회로: 1.5㎟ 노란색 연선</li><li>보호도체: 2.5㎟ 녹색-노란색 단선</li><li>PLC의 <strong>모든 단자</strong>에 절연튜브 적용</li><li>한 단자 최대 2가닥 · 나선 노출 2mm 미만</li><li>음영 구역 배선 · 타이 최대 100mm 간격</li></ul><p class="muted">세부 압착 규격과 예외는 원본 1페이지 표1을 확인하세요. 채점은 점수 없이 오류 개수로 표시됩니다.</p></div></section></div></main>`;bindHome();bindDocs();$('#start').onclick=()=>{if(attempt.start()){updateState();toast('측정을 시작했습니다. 시작 단자를 선택하세요.');}};$('#finish').onclick=()=>confirmAction('배선 작업 완료','배선 작업을 완료하시겠습니까? 완료 후에는 배선을 수정할 수 없습니다.',()=>{attempt.finish();persistCompleted();selectedTerminal=null;editing=null;updateState();renderBoard();renderDock();},'완료');$('#score').onclick=()=>{attempt.score(p);updateState();renderResults();};$('#power').onchange=e=>{if(attempt.state==='ready')p=getProblem(e.target.value);};$('#pending').onclick=showPending;$('#boardplus').onclick=()=>changeBoardZoom(25);$('#boardminus').onclick=()=>changeBoardZoom(-25);document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>selectDevice(b.dataset.device));renderForm();renderBoard();updateState();}
function changeBoardZoom(delta){boardZoom=Math.max(100,Math.min(250,boardZoom+delta));$('#board').style.width=boardZoom+'%';}
function selectDevice(id){selectedDevice=id;renderBoard();renderDock();}
function renderDock(){if(!$('#terminaldock'))return;const d=p.devices.find(x=>x.id===selectedDevice);$('#terminaldock').innerHTML=d?`<div class="terminalhead"><h3>${d.id} <span class="muted">단자 ${d.terminals.length}개</span></h3><span class="muted">${attempt.state==='running'?'연결할 단자를 선택하세요':'열람 가능 · 배선 잠금'}</span></div><div class="terminalbuttons">${d.terminals.map(id=>`<button data-terminal="${esc(id)}" class="${selectedTerminal===id?'selected':''} ${highlight?.terminalIds.includes(id)?'error':''}" title="${esc(id)}">${esc(p.terminalMap[id].name)}</button>`).join('')}</div><p class="docknote">${esc(d.position)}${d.id==='RY1'||d.id.startsWith('RY')?' · 핀 위치는 원본 6페이지 소켓 그림을 확인하세요.':''}</p>`:'<div class="empty">기구를 클릭하면 연결 가능한 단자를 확인할 수 있습니다.</div>';document.querySelectorAll('[data-terminal]').forEach(b=>b.onclick=()=>pickTerminal(b.dataset.terminal));if(d?.id.startsWith('RY')){const detail=document.createElement('details');detail.className='socketdetail';detail.innerHTML='<summary>원본 소켓 그림에서 단자 선택</summary><div class=socket><img src=assets/relay-socket.webp alt=원본6페이지14핀릴레이소켓></div>';const points={'8':[18,18],'7':[52,18],'6':[86,18],'5':[120,18],'4':[18,57],'3':[52,57],'2':[86,57],'1':[120,57],'14':[18,183],'13':[120,183],'12':[18,217],'11':[52,217],'10':[86,217],'9':[120,217]};for(const [name,[x,y]]of Object.entries(points)){const b=document.createElement('button');b.textContent=name;b.title=d.id+'.'+name;b.setAttribute('aria-label',d.id+' '+name+'번 원본 단자');b.style.left=x/138*100+'%';b.style.top=y/239*100+'%';b.className='socketpin';b.onclick=()=>pickTerminal(d.id+'.'+name);detail.querySelector('.socket').append(b);}$('#terminaldock').append(detail);}}
function pickTerminal(id){if(attempt.state!=='running'){toast('시작 버튼을 누르면 배선할 수 있습니다.');return;}if(!selectedTerminal){selectedTerminal=id;$('#fromLabel').textContent=id;toast('자재와 양쪽 접속부를 선택한 뒤 도착 단자를 클릭하세요.');}else if(selectedTerminal===id){selectedTerminal=null;$('#fromLabel').textContent='시작 단자를 선택하세요';}else{createWire(selectedTerminal,id);selectedTerminal=null;$('#fromLabel').textContent='시작 단자를 선택하세요';}renderDock();renderBoard();}
function knownPoint(t){const d=p.devices.find(x=>x.id===t.deviceId),i=d.terminals.indexOf(t.id);if(t.deviceId==='TB1')return [73+i*15.5,45];if(t.deviceId==='TB2')return [144+i*15.5,45];if(t.deviceId==='TB3')return [41,342+i*15.8];if(t.deviceId==='TB4')return [41,420+i*15];return [d.box[0]+d.box[2]/2,d.box[1]+d.box[3]/2];}
function renderBoard(){if(!$('#board'))return;document.querySelectorAll('[data-device]').forEach(b=>{b.classList.toggle('active',b.dataset.device===selectedDevice);b.classList.toggle('error',!!highlight?.deviceIds.includes(b.dataset.device));});$('#board').querySelectorAll('.knownpin').forEach(b=>b.remove());for(const t of p.terminals.filter(t=>t.deviceId.startsWith('TB'))){const [x,y]=knownPoint(t),b=document.createElement('button');b.className='knownpin'+(selectedTerminal===t.id?' selected':'')+(highlight?.terminalIds.includes(t.id)?' error':'');b.style.left=x/698*100+'%';b.style.top=y/599*100+'%';b.title=t.id;b.setAttribute('aria-label',t.id+' 단자');b.onclick=()=>{selectedDevice=t.deviceId;pickTerminal(t.id);};$('#board').append(b);}$('#wires').innerHTML=attempt.connections.map(w=>{const a=knownPoint(p.terminalMap[w.from]),b=knownPoint(p.terminalMap[w.to]),mid=(a[1]+b[1])/2,path=`M${a[0]},${a[1]} L${a[0]},${mid} L${b[0]},${mid} L${b[0]},${b[1]}`;return `<path class="wirepath ${highlight?.wireIds.includes(w.id)?'highlight':''}" d="${path}" stroke="${colors[w.color]||'#888'}" stroke-width="2.5"/><path class="wirepath hit" data-wire="${w.id}" d="${path}"/>`;}).join('');document.querySelectorAll('[data-wire]').forEach(b=>b.onclick=()=>focusWire(b.dataset.wire));}
function updateState(){if(!$('#start'))return;const running=attempt.state==='running',finished=['finished','graded'].includes(attempt.state);$('#start').disabled=attempt.state!=='ready';$('#finish').disabled=!running;$('#score').disabled=!finished;$('#power').disabled=attempt.state!=='ready';$('#stateLabel').textContent={ready:'문제 확인 · 시작 전',running:'배선 작업 중',finished:'작업 완료 · 작업판 잠금',graded:'채점 완료 · 작업판 잠금'}[attempt.state];$('#clocklabel').textContent=finished?'최종 작업시간':'경과시간';$('#clock').textContent=formatTime(attempt.elapsed());$('#wireform')?.querySelectorAll('input,select,button').forEach(x=>x.disabled=!running);renderWireList();}
setInterval(()=>{if(currentView==='session'&&$('#clock'))$('#clock').textContent=formatTime(attempt.elapsed());},100);
function confirmAction(title,text,fn,label='확인'){const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="actions"><button id="cancel">취소</button><button id="confirm" class="primary">${esc(label)}</button></div>`;document.body.append(d);d.querySelector('#cancel').onclick=()=>d.close();d.querySelector('#confirm').onclick=()=>{d.close();fn();};d.onclose=()=>d.remove();d.showModal();d.querySelector('#cancel').focus();}
function resetAttempt(){attempt.reset();try{localStorage.removeItem('pcq-last-completed');}catch{}}
function persistCompleted(){try{localStorage.setItem('pcq-last-completed',JSON.stringify({problemId:p.id,power:p.power,elapsedMs:attempt.elapsedMs,connections:attempt.connections,completedAt:new Date().toISOString()}));}catch{}}
function showPending(){const d=document.createElement('dialog');d.innerHTML=`<h2>확인 필요 · 채점에서 분리한 항목</h2>${p.pending.map(x=>`<p><strong>${x.title}</strong><br>${x.detail}</p>`).join('')}<div class="actions"><button>닫기</button></div>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();}
function options(values,selected){return values.map(v=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('');}
function renderForm(w=null){
 const e=side=>w?.ends[side]??{crimp:'1.5-3Y',tube:false,orientation:'위',doubleMount:'미지정',bareMm:0,insulationClamped:false,tight:true};
 $('#wireform').innerHTML=`<div class="formgrid"><label>전선 종류<select id="kind">${options(['연선','단선'],w?.kind??'연선')}</select></label><label>굵기 (㎟)<select id="area">${options([1.5,2.5],w?.area??1.5)}</select></label><label>색상<select id="color">${options(Object.keys(colors),w?.color??'노란색')}</select></label></div><div class="endgrid">${['from','to'].map((s,i)=>`<div class="endpoint"><h3>${i?'도착':'시작'} 접속부 ${w?esc(w[s]):''}</h3><label>압착단자<select id="${s}Crimp">${options(crimpOptions,e(s).crimp)}</select></label><label class="check"><input type="checkbox" id="${s}Tube" ${e(s).tube?'checked':''}>절연튜브 적용</label><details><summary class="muted">체결 상태 설정</summary><label>압착단자 방향 (확인 필요)<select id="${s}Orientation">${options(['위','아래','왼쪽','오른쪽'],e(s).orientation)}</select></label><label>2개 체결 방식 (확인 필요)<select id="${s}Double">${options(['미지정','같은 방향 겹침','서로 마주봄','등을 맞댐'],e(s).doubleMount)}</select></label><label>나선 노출 (mm)<input id="${s}Bare" type="number" min="0" max="30" step="0.5" value="${e(s).bareMm}"></label><label class="check"><input type="checkbox" id="${s}Clamped" ${e(s).insulationClamped?'checked':''}>피복이 단자에 물림</label><label class="check"><input type="checkbox" id="${s}Tight" ${e(s).tight?'checked':''}>나사를 견고하게 조임</label></details></div>`).join('')}</div><details class="workmanship"><summary>배선 경로·마감 상태 입력 (실물 검사는 별도 확인)</summary><div class="formgrid"><label class="check"><input type="checkbox" id="inDuct" ${w?.route?.inDuct===false?'':'checked'}>음영 구역을 따름</label><label class="check"><input type="checkbox" id="touchDevice" ${w?.route?.touchesDevice?'checked':''}>기구에 전선이 닿음</label><label>타이 간격 (mm)<input id="tieSpacing" type="number" min="0" max="1000" value="${w?.route?.tieSpacingMm??100}"></label><label class="check"><input type="checkbox" id="tieTrimmed" ${w?.route?.tieTrimmed===false?'':'checked'}>타이 잔여 부분 제거</label></div></details><div class="toolbar"><span id="fromLabel" class="status">${w?`${w.id} 수정 중`:selectedTerminal??'시작 단자를 선택하세요'}</span>${w?'<button id="saveEdit" class="primary">변경 저장</button><button id="cancelEdit">취소</button>':'<button id="cancelPick">단자 선택 취소</button>'}<button id="undo">실행취소</button><button id="clear" class="danger">배선 초기화</button></div>`;
 $('#undo').onclick=()=>{attempt.undo();selectedTerminal=null;editing=null;renderForm();renderBoard();renderWireList();renderDock();updateState();};
 $('#clear').onclick=()=>confirmAction('배선 초기화','현재 배선을 모두 삭제합니다. 스톱워치는 계속 측정됩니다.',()=>{attempt.mutate(a=>a.splice(0));selectedTerminal=null;editing=null;renderForm();renderBoard();renderWireList();renderDock();},'삭제');
 if(w){$('#saveEdit').onclick=()=>{try{attempt.update(w.id,{...readForm(),from:w.from,to:w.to});editing=null;renderForm();renderBoard();renderWireList();toast('전선과 양쪽 접속부를 수정했습니다.');}catch(e){toast(e.message);}};$('#cancelEdit').onclick=()=>{editing=null;renderForm();};}
 else $('#cancelPick').onclick=()=>{selectedTerminal=null;renderForm();renderDock();};
 if(attempt.state!=='running')$('#wireform').querySelectorAll('input,select,button').forEach(x=>x.disabled=true);
}
function readForm(){const number=id=>{const el=$(id),v=Number(el.value);if(el.value===''||!Number.isFinite(v)||v<0||!el.checkValidity())throw Error('노출 길이와 타이 간격에 유효한 숫자를 입력하세요.');return v;};const end=s=>({crimp:$('#'+s+'Crimp').value,tube:$('#'+s+'Tube').checked,orientation:$('#'+s+'Orientation').value,doubleMount:$('#'+s+'Double').value,bareMm:number('#'+s+'Bare'),insulationClamped:$('#'+s+'Clamped').checked,tight:$('#'+s+'Tight').checked});return {kind:$('#kind').value,area:Number($('#area').value),color:$('#color').value,ends:{from:end('from'),to:end('to')},route:{inDuct:$('#inDuct').checked,touchesDevice:$('#touchDevice').checked,tieSpacingMm:number('#tieSpacing'),tieTrimmed:$('#tieTrimmed').checked}};}
function renderWireList(){if(!$('#wirelist'))return;$('#wirelist').innerHTML=attempt.connections.length?attempt.connections.map(w=>`<div class="wirerow"><span class="swatch" style="background:${colors[w.color]}"></span><div class="wirelabel"><strong>${w.id}</strong> ${esc(w.from)} ↔ ${esc(w.to)}<div class="muted">${w.area}㎟ ${w.kind} · ${w.color} · ${w.ends.from.crimp} / ${w.ends.to.crimp}</div></div><button data-focus="${w.id}">위치</button><button data-edit="${w.id}" ${attempt.state!=='running'?'disabled':''}>수정</button><button data-delete="${w.id}" class="danger" ${attempt.state!=='running'?'disabled':''}>삭제</button></div>`).join(''):'<div class="empty">아직 연결한 전선이 없습니다. 시작 → 시작 단자 → 자재 설정 → 도착 단자 순서로 배선하세요.</div>';document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focusWire(b.dataset.focus));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{if(attempt.state!=='running')return;editing=b.dataset.edit;selectedTerminal=null;renderForm(attempt.connections.find(w=>w.id===editing));$('#materials').scrollIntoView({behavior:'smooth',block:'center'});});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{attempt.remove(b.dataset.delete);if(editing===b.dataset.delete){editing=null;renderForm();}highlight=null;renderBoard();renderWireList();});}
function createWire(from,to){if(editing){toast('현재 변경을 저장하거나 취소한 뒤 새 전선을 연결하세요.');return;}try{if(attempt.connections.some(w=>[w.from,w.to].includes(from)&&[w.from,w.to].includes(to))){toast('같은 두 단자 사이에 이미 전선이 있습니다. 기존 전선을 수정하세요.');return;}const id=attempt.add({...readForm(),from,to});highlight=null;renderBoard();renderWireList();toast(`${id} · ${from} ↔ ${to} 연결`);}catch(e){toast(e.message);}}
function renderResults(){const r=attempt.result,el=$('#results');el.hidden=false;el.innerHTML=`<div class="panelhead"><h2>채점 결과</h2><button id="retry" class="primary">다시 풀기</button></div><div class="resultstats"><div><span class="muted">최종 작업시간</span><strong>${formatTime(attempt.elapsedMs)}</strong></div><div><span class="muted">틀린 항목 · 확정 규칙 기준</span><strong>${r.count}개</strong></div></div><div class="notice">확인 필요 ${r.pending.length}개 범주는 미판정입니다. 오류가 0개여도 전체 시공 적합 판정이 아닙니다.</div>${r.errors.length?r.errors.map((e,i)=>`<button class="erroritem" data-error="${i}"><strong>오류 ${i+1} · ${esc(e.type)}</strong><p>${esc(e.wrong)}</p><small>올바른 방법: ${esc(e.correct)}</small><p class="muted">${esc(e.wireIds.join(' · ')||'전선 추가 필요')} · 위치 확인 ↗</p></button>`).join(''):'<div class="empty">확정된 NET과 명시된 작업 규칙에서 오류가 발견되지 않았습니다.</div>'}<details class="pendinglist"><summary>확인 필요 항목 ${r.pending.length}개 범주 / 보류 연결 ${r.reviews.length}개</summary>${r.pending.map(x=>`<p><strong>${esc(x.title)}</strong><br>${esc(x.detail)}</p>`).join('')}${r.reviews.map(x=>`<p>${esc(x.wireIds.join(', '))} · ${esc(x.detail)}</p>`).join('')}</details>`;$('#retry').onclick=()=>confirmAction('같은 문제 다시 풀기','기존 배선, 채점 결과와 작업시간을 초기화합니다.',()=>{const power=p.power;resetAttempt();p=getProblem(power);session();$('#power').value=power;},'다시 풀기');document.querySelectorAll('[data-error]').forEach(b=>b.onclick=()=>{highlight=r.errors[Number(b.dataset.error)];selectedDevice=highlight.deviceIds[0];document.querySelectorAll('[data-error]').forEach(x=>x.classList.toggle('active',x===b));renderBoard();renderDock();focusBoardDevice();});try{localStorage.setItem('pcq-last-completed',JSON.stringify({problemId:p.id,power:p.power,elapsedMs:attempt.elapsedMs,connections:attempt.connections,result:r,completedAt:new Date().toISOString()}));}catch{}el.scrollIntoView({behavior:'smooth',block:'start'});}
function focusBoardDevice(){const d=document.querySelector(`[data-device="${selectedDevice}"]`);d?.scrollIntoView({behavior:'smooth',block:'center',inline:'center'});}
function focusWire(id){const w=attempt.connections.find(w=>w.id===id);if(!w)return;highlight={wireIds:[id],terminalIds:[w.from,w.to],deviceIds:[p.terminalMap[w.from].deviceId,p.terminalMap[w.to].deviceId]};selectedDevice=p.terminalMap[w.from].deviceId;renderBoard();renderDock();focusBoardDevice();}
window.addEventListener('beforeunload',e=>{if(attempt.state==='running'){e.preventDefault();e.returnValue='';}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_pcq_attempt',title:'배선 실습 상태 읽기',description:'현재 실습 상태, 경과시간, 연결한 전선과 완료 후 채점 결과를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('빈 객체만 허용합니다.');return {problemId:p.id,state:attempt.state,elapsedMs:attempt.elapsed(),connections:structuredClone(attempt.connections),result:attempt.result};}})).catch(()=>{});}catch{}}
home();
